evidence.snippet:
evidence: Type.Optional(
	Type.Object(
		{
			budget: Type.Optional(
				Type.Union([
					Type.Integer({ minimum: 0 }),
					Type.String({ pattern: "^(0|[1-9][0-9]{0,15})(B|KiB|MiB|GiB|TiB)$" }),
				]),
			),
		},
		strict,
	),
),

// The configuration without its display-only keys, which change how a review reads and never what a check finds, so a
// change to one reuses the run. `language` joins them when it lands.
function decisive(config: MelianConfig): unknown {
	const { output: _, publish, ...rest } = config;
	const { emoji: __, ...kept } = publish;
	return { ...rest, publish: kept };
}

const facts: CheckRequestInput = {
	config: input.config,
	source: input.source,
	tools: (await ToolProvisioning.manifest()).toJSON(),
	analysers: { biome: analyser("biome"), tsc: analyser("tsc") },
	install: installDigests(repoRoot),
	...(input.config.static.mutation.enabled
		? {
				mutation: {
					stryker: {
						version: strykerVersion(repoRoot),
						installation: mutationInstallation(repoRoot),
						source: staticToolSource(repoRoot, "mutation"),
					},
					writer: input.writer ?? null,
					// A cold run is another run of the check: a provisional result of the same head must not stand in for it.
					cold: input.cold === true,
				},
			}
		: {}),
	// The local environment runs every tool on this host. One that runs tools elsewhere must supply its own host facts.
	host: hostFacts(),
	lang: toolLocale(),
	...(input.source.kind === "worktree" ? { policy: await worktreePolicy(input) } : {}),
};
const asked = checkRequest(facts);

if (held + adding > this.budget)
	throw new EvidenceError(
		"budget",
		`${join(this.directory, pointer.changeset)}/ would take the evidence directory past its budget: it holds ${held} bytes, this evidence needs ${adding} more, and evidence.budget is ${this.budget}. melian store prune keeps evidence. Raise evidence.budget in your configuration until the prune lands in issue #627 (https://github.com/melian-agent/melian/issues/627). This refusal wrote no file and lost no evidence already kept`,
	);
